class NestedIterator {
  private flat: number[] = [];
  private pos = 0;

  constructor(nested: any[]) {
    const walk = (list: any[]) => {
      for (const x of list) Array.isArray(x) ? walk(x) : this.flat.push(x);
    };
    walk(nested);
  }

  hasNext(): boolean { return this.pos < this.flat.length; }

  next(): number { return this.flat[this.pos++]; }
}

