class NestedIterator {
  private stack: [any[], number][];

  constructor(nested: any[]) {
    this.stack = [[nested, 0]];
  }

  // Advance until the top frame points at a number, or nothing is left.
  private settle(): void {
    while (this.stack.length) {
      const top = this.stack[this.stack.length - 1];
      const [list, i] = top;
      if (i === list.length) { this.stack.pop(); continue; }
      if (!Array.isArray(list[i])) return;
      top[1]++; // step past the sublist in the parent before entering it
      this.stack.push([list[i], 0]);
    }
  }

  hasNext(): boolean {
    this.settle();
    return this.stack.length > 0;
  }

  next(): number {
    this.settle();
    const top = this.stack[this.stack.length - 1];
    return top[0][top[1]++];
  }
}

