        # advance until the top frame points at a number, or nothing is left
        st = self.stack
        while st:
            top = st[-1]
            lst, i = top
            if i == len(lst):
                st.pop()
                continue
            if not isinstance(lst[i], list):
                return
            top[1] += 1  # step past the sublist in the parent before entering it
            st.append([lst[i], 0])

    def hasNext(self) -> bool:
        self._settle()
        return bool(self.stack)

    def next(self) -> int:
        self._settle()
        top = self.stack[-1]
        top[1] += 1
        return top[0][top[1] - 1]

